def _topup_logs(self):
    return ActivityLog.objects.filter(team_id=self.team.id, scope="AIGatewayCredit", activity="credit_added")

def _submit_credit(self, duplicate: bool, impersonated: bool = False) -> None:
    result = CreditResult(
        team_id=self.team.id, entry_id="entry-1", amount_usd="25.000000", balance_usd="35.000000", duplicate=duplicate
    )
    request = self._post({"amount_usd": "25", "reason": "support goodwill", "form_nonce": "n"})
    with (
        patch("posthog.admin.admins.team_admin.add_credit", return_value=result),
        patch("posthog.admin.admins.team_admin.is_impersonated_session", return_value=impersonated),
    ):
        self.admin.add_ai_gateway_credit_view(request, str(self.team.pk))

@parameterized.expand([("direct", False), ("impersonated", True)])
def test_add_credit_records_who_topped_up(self, _name: str, impersonated: bool) -> None:
    self._submit_credit(duplicate=False, impersonated=impersonated)

    log = self._topup_logs().get()
    assert log.item_id == "entry-1"
    assert log.user == self.user
    assert log.was_impersonated is impersonated
    assert log.detail["context"] == {
        "amount_usd": "25.000000",
        "reason": "support goodwill",
        "balance_usd": "35.000000",
    }

